/* =====================================================================
 * RECIPE DATABASE + IMAGE MATCHING  (v84)
 * One shared store used by:   RECIPE (load) screen  <->  CALIBRATE screen
 *   - Storage : SQLite on server (/api/recipes).
 *   - Load by : NAME dropdown | IMAGE thumbnail / image file | LIVE CAMERA
 *   - Calibrate SAVE writes here, Load reads from here.
 * ===================================================================== */
const SEED_VERSION = 1;
const RECIPE_DEFAULTS = {
  id:'', name:'', operator:'', product:'', netWeight:25, notes:'',
  repeatLength:740, width:495, material:'BOPP', markWindow:40, markOffset:0, sTensionTarget:5.0,
  frontSensor:0, frontMark:0, frontBackground:0, backSensor:0, backMark:0, backBackground:0,
  imageName:'', imageType:'', imageDataUrl:'', imageSig:null,
  createdAt:0, updatedAt:0, lastLoadedAt:0, loadedVia:''
};
function recipeClone(v){ return JSON.parse(JSON.stringify(v)); }
function normalizeRecipe(r){ return Object.assign({}, RECIPE_DEFAULTS, recipeClone(r || {})); }
function recipeEsc(v){ return String(v==null?'':v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }

