/* =====================  IMAGE FINGERPRINT / MATCHING  ===================== */
const RecipeMatch = (() => {
  const VER = 3, N = 96, NB = 16;      // bins: 0 black | 1-3 greys | 4-15 twelve hues
  const MATCH_OK = 0.60;               // best score needed to auto-select (60% accuracy threshold)
  const MATCH_MARGIN = 0.04;           // margin above runner-up
  function binOf(r,g,b,vs){
    const mx=Math.max(r,g,b), mn=Math.min(r,g,b), d=mx-mn, s=mx?d/mx:0, v=Math.min(1,(mx/255)*vs);
    if(v<0.2) return 0;                                    // black
    if(s<0.25) return v<0.5 ? 1 : (v<0.78 ? 2 : 3);        // greys / white
    let h;
    if(d===0) h=0; else if(mx===r) h=((g-b)/d+6)%6; else if(mx===g) h=(b-r)/d+2; else h=(r-g)/d+4;
    return 4 + (Math.floor(h/6*12)%12);
  }
  function norm(a){ let t=0; for(const x of a) t+=x; return a.map(x=>t?+(x/t).toFixed(5):0); }
  /* crop=true : take the centred portrait window of a landscape frame (a bag held upright, as on a camera) */
  function signature(src, crop){
    const sw=src.videoWidth||src.naturalWidth||src.width, sh=src.videoHeight||src.naturalHeight||src.height;
    let sx=0, cw=sw;
    if(crop && sw>sh*0.9){ cw=Math.round(sh*0.68); sx=Math.round((sw-cw)/2); }
    const c=document.createElement('canvas'); c.width=N; c.height=N;
    const g=c.getContext('2d',{willReadFrequently:true});
    g.drawImage(src,sx,0,cw,sh,0,0,N,N);
    const px=g.getImageData(0,0,N,N).data;
    // brightness normalisation: scale so the 95th-percentile brightness is ~1 (dim photos still land in the same bins)
    const hist=new Array(64).fill(0);
    for(let i=0;i<px.length;i+=4) hist[Math.min(63,Math.floor(Math.max(px[i],px[i+1],px[i+2])/4))]++;
    let acc=0, p95=255; for(let i=0;i<64;i++){ acc+=hist[i]; if(acc>=N*N*0.95){ p95=i*4+3; break; } }
    const vs=1/Math.max(0.45,Math.min(1,p95/255));
    const all=new Array(NB).fill(0), mid=new Array(NB).fill(0);
    for(let y=0;y<N;y++) for(let x=0;x<N;x++){
      const i=(y*N+x)*4, b=binOf(px[i],px[i+1],px[i+2],vs);
      all[b]++; if(x>=N*0.2 && x<N*0.8 && y>=N*0.15 && y<N*0.85) mid[b]++;
    }
    const chroma=all.slice(4); let ct=0; for(const x of chroma) ct+=x;
    return { v:VER, a:norm(all), c:norm(mid), h:norm(chroma), f:+(ct/(N*N)).toFixed(4) };
  }
  /* what to compare a query image with: centred portrait crop AND the whole frame */
  function signatures(src){ return [signature(src,true), signature(src,false)]; }
  function inter(a,b){ let s=0; for(let i=0;i<a.length;i++) s+=Math.min(a[i],b[i]); return s; }
  function score(q,r){
    const wh=0.4*Math.min(1,q.f/0.08,r.f/0.08);          // colour-only term, trusted only when both images have colour
    return (0.3*inter(q.a,r.a)+0.3*inter(q.c,r.c)+wh*inter(q.h,r.h))/(0.6+wh);
  }
  function rank(sigs, recipes){
    sigs=Array.isArray(sigs)?sigs:[sigs];
    return recipes.filter(r=>r.imageSig && r.imageSig.v===VER)
      .map(r=>({id:r.id,name:r.name,score:Math.max(...sigs.map(q=>score(q,r.imageSig)))}))
      .sort((x,y)=>y.score-x.score);
  }
  function verdict(ranked){
    if(!ranked.length) return 'none';
    const a=ranked[0], b=ranked[1];
    return (a.score>=MATCH_OK && (!b || a.score-b.score>=MATCH_MARGIN)) ? 'confident' : 'low';
  }
  function loadImage(url){ return new Promise((ok,no)=>{ const i=new Image(); i.onload=()=>ok(i); i.onerror=()=>no(new Error('image decode failed')); i.src=url; }); }
  async function sigFromDataUrl(url){ return signature(await loadImage(url),false); }
  async function downscale(url,maxSide,q){
    const im=await loadImage(url), k=Math.min(1,maxSide/Math.max(im.naturalWidth,im.naturalHeight));
    const c=document.createElement('canvas'); c.width=Math.max(1,Math.round(im.naturalWidth*k)); c.height=Math.max(1,Math.round(im.naturalHeight*k));
    c.getContext('2d').drawImage(im,0,0,c.width,c.height); return c.toDataURL('image/jpeg',q||0.8);
  }
  /* Best-effort QR / barcode read (needs a browser with BarcodeDetector). */
  async function readCode(canvas){
    try{
      if(!('BarcodeDetector' in window)) return null;
      const det=new BarcodeDetector({formats:['qr_code','code_128','code_39','data_matrix']});
      const res=await det.detect(canvas); return res && res[0] ? String(res[0].rawValue||'') : null;
    }catch(e){ return null; }
  }
  function parseCode(text){
    const out={recipe:'',operator:''};
    String(text).split(/[;|\n]/).forEach(p=>{
      const m=p.match(/^\s*(recipe|job|name|op|operator)\s*[:=]\s*(.+)$/i);
      if(m){ if(/^op/i.test(m[1])) out.operator=m[2].trim(); else out.recipe=m[2].trim(); }
    });
    if(!out.recipe && !out.operator) out.recipe=String(text).trim();
    return out;
  }
  return { VER, MATCH_OK, MATCH_MARGIN, signature, signatures, score, rank, verdict, loadImage, sigFromDataUrl, downscale, readCode, parseCode };
})();

/* =========================  RECIPE DATABASE  ========================= */
const RecipeDB = (() => {
  const DB_NAME='ricevision_hmi_db', LS_KEY='ricevision_hmi_db_ls';
  let idb=null, list=[], ops=[], activeId='', seedVersion=0, mode='memory', ready=false;
  const uid=()=>'r'+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
  const norm=s=>String(s||'').trim().toLowerCase();

  function openIdb(){
    return new Promise(res=>{
      try{
        if(!window.indexedDB) return res(null);
        const rq=indexedDB.open(DB_NAME,1);
        rq.onupgradeneeded=()=>{ const d=rq.result;
          if(!d.objectStoreNames.contains('recipes')) d.createObjectStore('recipes',{keyPath:'id'});
          if(!d.objectStoreNames.contains('meta')) d.createObjectStore('meta',{keyPath:'key'}); };
        rq.onsuccess=()=>res(rq.result); rq.onerror=()=>res(null); rq.onblocked=()=>res(null);
      }catch(e){ res(null); }
    });
  }
  const idbReq=r=>new Promise((ok,no)=>{ r.onsuccess=()=>ok(r.result); r.onerror=()=>no(r.error); });
  const idbAll=store=>idbReq(idb.transaction(store).objectStore(store).getAll());
  function idbTx(store,fn){
    return new Promise((ok,no)=>{ const t=idb.transaction(store,'readwrite'); fn(t.objectStore(store));
      t.oncomplete=()=>ok(); t.onerror=()=>no(t.error); t.onabort=()=>no(t.error); });
  }
  function lsWrite(){ mode='memory'; }
  async function persistRecipe(r){ if(idb) await idbTx('recipes',s=>s.put(r)); else lsWrite(); }
  async function persistMeta(){
    if(idb){ try{ await idbTx('meta',s=>{ s.put({key:'operators',value:ops}); s.put({key:'activeId',value:activeId}); s.put({key:'seedVersion',value:seedVersion}); }); }catch(e){} }
    else lsWrite();
  }

  async function init(){
    idb=await openIdb(); let meta={};
    if(idb){
      try{ list=await idbAll('recipes'); (await idbAll('meta')).forEach(m=>meta[m.key]=m.value); mode='IndexedDB'; }
      catch(e){ idb=null; list=[]; }
    }
    if(!idb){ mode='memory'; }
    ops=Array.isArray(meta.operators)?meta.operators.slice():[]; activeId=meta.activeId||''; seedVersion=meta.seedVersion||0;
    list=list.map(normalizeRecipe);

    // Recipe library loaded from SQLite server /api/recipes
    // seed the supplied designs (once). A same-named legacy recipe is upgraded instead of duplicated.
    if(seedVersion<SEED_VERSION){
      RECIPE_SEEDS.forEach(s=>{
        const seed=normalizeRecipe(s), have=list.find(r=>r.id===s.id||norm(r.name)===norm(s.name));
        if(have){ if(!have.imageDataUrl){ const keep={id:have.id,operator:have.operator||seed.operator,createdAt:have.createdAt}; Object.assign(have,seed,keep); } }
        else { seed.createdAt=Date.now(); seed.updatedAt=seed.createdAt; list.push(seed); }
      });
      seedVersion=SEED_VERSION;
    }
    ['Operator 1','Operator 2'].forEach(o=>{ if(!ops.some(x=>norm(x)===norm(o))) ops.push(o); });
    list.forEach(r=>{ if(r.operator && !ops.some(x=>norm(x)===norm(r.operator))) ops.push(r.operator); });

    // fingerprints for every stored image (needed for IMAGE / CAMERA matching)
    for(const r of list){
      if(r.imageDataUrl && (!r.imageSig || r.imageSig.v!==RecipeMatch.VER)){
        try{ r.imageSig=await RecipeMatch.sigFromDataUrl(r.imageDataUrl); }catch(e){ r.imageSig=null; }
      }
    }
    if(idb){ for(const r of list) await persistRecipe(r); } else lsWrite();
    await persistMeta(); ready=true;
  }

  const api = {
    init,
    isReady:()=>ready, storageMode:()=>mode,
    list:()=>list.slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),undefined,{sensitivity:'base'})),
    count:()=>list.length,
    get:id=>{ const r=list.find(x=>x.id===id); return r?recipeClone(r):null; },
    findByName:n=>{ const r=list.find(x=>norm(x.name)===norm(n)); return r?recipeClone(r):null; },
    operators:()=>ops.slice(),
    addOperator:n=>{ n=String(n||'').trim(); if(!n) return ''; const e=ops.find(x=>norm(x)===norm(n)); if(e) return e; ops.push(n); persistMeta(); return n; },
    activeId:()=>activeId,
    setActive:id=>{ activeId=id||''; persistMeta(); },
    async save(rec){
      const r=normalizeRecipe(rec); const now=Date.now();
      r.name=String(r.name).trim(); r.operator=String(r.operator).trim();
      if(!r.id) r.id=uid();
      const prev=list.find(x=>x.id===r.id);
      r.createdAt=(prev&&prev.createdAt)||r.createdAt||now; r.updatedAt=now;
      if(r.imageDataUrl){
        if(!r.imageSig || r.imageSig.v!==RecipeMatch.VER){ try{ r.imageSig=await RecipeMatch.sigFromDataUrl(r.imageDataUrl); }catch(e){ r.imageSig=null; } }
      } else r.imageSig=null;
      const i=list.findIndex(x=>x.id===r.id); if(i>=0) list[i]=r; else list.push(r);
      if(r.operator) api.addOperator(r.operator);
      await persistRecipe(r); await persistMeta();
      return recipeClone(r);
    },
    async remove(id, name){
      const normN = norm(name);
      list = list.filter(x => x.id !== id && (!normN || norm(x.name) !== normN));
      if(activeId === id || (normN && norm(activeId) === normN)) activeId = '';
      if(idb) {
        try {
          await idbTx('recipes', s => {
            s.delete(id);
          });
        } catch(e) {}
      } else lsWrite();
      await persistMeta();
    }
  };
  return api;
})();
window.RecipeDB=RecipeDB; window.RecipeMatch=RecipeMatch;

/* =====================  APPLY / ACTIVE RECIPE & JOB STATE  ===================== */
function getRecipeCamImage(rec) {
  if (!rec) return '/images/thangamayil_front_back_0mm.jpg';
  const n = (rec.name || '').toLowerCase();
  if (n.includes('thangamayil')) return '/images/thangamayil_front_back_0mm.jpg';
  if (n.includes('india')) return '/images/indiagate_front_back_0mm.jpg';
  if (n.includes('kohinoor')) return '/images/kohinoor_front_back_0mm.jpg';
  if (n.includes('veera') || n.includes('sivaji')) return '/images/veerashivaji_front_back_0mm.jpg';
  if (n.includes('royal') || n.includes('bullet')) return '/images/royal_bullet_front_back_0mm.jpg';
  return '/images/thangamayil_front_back_0mm.jpg';
}

function updateDbRefPlate(rec){
  const plate = document.getElementById('recipe-db-ref-plate');
  if(!plate) return;
  const imgUrl = (rec && (rec.frontImageUrl || rec.imageUrl || rec.imageDataUrl)) || (typeof getRecipeImageUrl === 'function' ? getRecipeImageUrl(rec) : '') || '/images/thangamayil_25kg.jpg';
  let curImg = document.getElementById('db-ref-img');
  if (!curImg) {
    plate.innerHTML = `<img id="db-ref-img" src="${imgUrl}" alt="${recipeEsc(rec ? rec.name : 'DB Ref')}" style="width:100%;height:100%;object-fit:contain;background:#060a10;display:block;">`;
  } else if (curImg.getAttribute('src') !== imgUrl) {
    curImg.src = imgUrl;
    curImg.alt = recipeEsc(rec ? rec.name : 'DB Ref');
  }

  // Update recipe camera metadata
  updateLiveCamForRecipe(rec);
}

function updateLiveCamForRecipe(rec){
  const curMode = (window.HMI_STATE?.stn2?.mode || 'OFF');
  if (curMode === 'OFF') {
    if (typeof stopLiveCamera === 'function') stopLiveCamera();
    return;
  }
  const homeVid = document.getElementById('home-cam-video');
  const liveCamImg = document.getElementById('recipe-live-cam-img');
  const fullVid = document.getElementById('full-cam-video');
  const fullCamImg = document.getElementById('full-cam-preview-img');

  // If live camera is actively streaming in AUTO or MAN, do not clobber it with a static dummy image!
  const isVideoStreaming = (homeVid && homeVid.style.display !== 'none' && homeVid.srcObject) ||
                           (fullVid && fullVid.style.display !== 'none' && fullVid.srcObject);
  const isServerStreaming = (liveCamImg && liveCamImg.src && liveCamImg.src.includes('/api/camera/stream'));

  if (!isVideoStreaming && !isServerStreaming) {
    if (curMode === 'AUTO' || curMode === 'MAN') {
      if (typeof startLiveCameraFeed === 'function') {
        startLiveCameraFeed(true);
      }
    }
  }

  const camMatch = document.getElementById('cam-matched-name');
  if (camMatch) {
    camMatch.textContent = `${rec ? rec.name : 'Recipe'} (Front & Back)`;
  }
  // Calculate optical error from the distance of the two images (front and back)
  if (typeof calculateFrontBackDistance === 'function') {
    calculateFrontBackDistance(rec);
  }
}

async function calculateFrontBackDistance(rec) {
  const rid = (rec && rec.numericId) ? rec.numericId : 0;
  const err = window.activeCamError || 'live';
  try {
    let res;
    let blob = null;
    const activeVid = [
      document.getElementById('full-cam-video'),
      document.getElementById('home-cam-video')
    ].find(v => v && v.style.display !== 'none' && v.videoWidth > 0);

    if (activeVid && err === 'live') {
      try {
        const canvas = document.createElement('canvas');
        canvas.width = Math.min(860, activeVid.videoWidth);
        canvas.height = Math.round(canvas.width * activeVid.videoHeight / activeVid.videoWidth);
        canvas.getContext('2d').drawImage(activeVid, 0, 0, canvas.width, canvas.height);
        blob = await new Promise(r => canvas.toBlob(r, 'image/jpeg', 0.85));
      } catch(e) {}
    }

    if (blob) {
      res = await fetch(`/api/camera/compare_front_back?error=${encodeURIComponent(err)}&recipe_id=${rid}`, {
        method: 'POST',
        headers: { 'Content-Type': 'image/jpeg' },
        body: blob
      });
    } else {
      res = await fetch(`/api/camera/compare_front_back?error=${encodeURIComponent(err)}&recipe_id=${rid}`);
    }

    if (res && res.ok) {
      const data = await res.json();
      if (data) {
        if (typeof updateErrorPercentageDisplay === 'function') {
          updateErrorPercentageDisplay(data);
        }
        if (data.ok) {
          const dyMm = (typeof data.offset_y_mm === 'number') ? data.offset_y_mm : ((typeof data.error_mm === 'number') ? data.error_mm : 0.0);
          updateDistanceDisplay(dyMm, data);
        }
        return;
      }
    }
  } catch(e) {}
  updateDistanceDisplay(0.0, { status: 'IN SPEC' });
}

function updateDistanceDisplay(distanceMm, data) {
  const isStn2Off = (window.HMI_STATE?.stn2?.mode === 'OFF');
  if (isStn2Off) distanceMm = 0.0;
  
  const errValEl = document.getElementById('live-cam-err-val');
  const absErr = Math.abs(distanceMm);
  const isPass = (absErr <= 7.0) || ((data && data.status) === 'IN SPEC');
  const sign = distanceMm > 0 ? '+' : (distanceMm < 0 ? '' : '');
  const text = absErr < 0.05 ? '0.0 mm' : `${sign}${distanceMm.toFixed(1)} mm`;
  const color = (absErr <= 7.0) ? '#10b981' : (absErr <= 15.0 ? '#f59e0b' : '#f85149');
  if (errValEl) {
    errValEl.textContent = text;
    errValEl.style.color = isStn2Off ? '#64748b' : color;
  }
  // Note: STN 2 ruler & mark indicator are driven exclusively by FBARX link (updateRepAndRulerDisplay)
  const hudPill = document.getElementById('hud-error-pill');
  if (hudPill) {
    const dxMm = (typeof data?.offset_x_mm === 'number') ? data.offset_x_mm : 0.0;
    const dxSign = dxMm > 0 ? '+' : '';
    const dxStr = Math.abs(dxMm) < 0.05 ? '0.0mm' : `${dxSign}${dxMm.toFixed(1)}mm`;
    hudPill.textContent = `REGISTRATION: ${text} • ALIGN (ΔX): ${dxStr}`;
    hudPill.style.color = color;
    hudPill.style.borderColor = color;
  }
  const fullStat = document.getElementById('full-cam-reg-stat');
  if (fullStat) {
    fullStat.textContent = `DISTANCE (F-B): ${text} (${(data && data.status) || (isPass ? 'IN SPEC' : 'OUT OF SPEC')})`;
    fullStat.style.color = color;
  }
  const fpsStat = document.getElementById('full-cam-fps-stat');
  if (fpsStat && data && data.scale_px_per_mm) {
    fpsStat.textContent = `SCALE: ${data.scale_px_per_mm.toFixed(1)} px/mm • DIST: ${data.distance_px ? data.distance_px.toFixed(1) + 'px' : '—'} • ${(data.method || 'line').toUpperCase()}`;
  }
  const confVal = document.getElementById('cam-conf-val');
  if (confVal && data && typeof data.confidence === 'number') {
    confVal.textContent = data.confidence.toFixed(2);
  }
  const lblF = document.getElementById('hud-label-front');
  const lblB = document.getElementById('hud-label-back');
  if (lblF && data && typeof data.front_pct === 'number') {
    lblF.textContent = `FRONT: ${data.front_pct.toFixed(1)}%`;
  }
  if (lblB && data && typeof data.back_pct === 'number') {
    lblB.textContent = `BACK: ${data.back_pct.toFixed(1)}%`;
  }
  const lineF = document.getElementById('hud-line-front');
  const lineB = document.getElementById('hud-line-back');
  if (lineF && lineB) {
    const show = Boolean(data && typeof data.front_line_px === 'number');
    lineF.style.display = show ? 'block' : 'none';
    lineB.style.display = show ? 'block' : 'none';
  }
}
window.getRecipeCamImage = getRecipeCamImage;
window.updateLiveCamForRecipe = updateLiveCamForRecipe;
window.calculateFrontBackDistance = calculateFrontBackDistance;
window.updateDistanceDisplay = updateDistanceDisplay;

function updateCalOverlayFields(rec){
  if(!rec) return;
  const setTxt = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  setTxt('cal-recipe-name', rec.name || '—');
  setTxt('cal-repeat', `${rec.repeatLength} mm`);
  setTxt('cal-width', `${rec.width} mm`);
  setTxt('cal-window', `${rec.markWindow} mm`);
  setTxt('cal-offset', `${Number(rec.markOffset) > 0 ? '+' : ''}${rec.markOffset} mm`);
  setTxt('cal-tension', `${Number(rec.sTensionTarget || 0).toFixed(1)} kg`);
  setTxt('cal-front', String(rec.frontSensor || 0));
  setTxt('cal-back', String(rec.backSensor || 0));
}

let toastTimer = null;
function showToast(msg, bad=false){
  let t = document.getElementById('p1-toast');
  if(!t){
    t = document.createElement('div');
    t.id = 'p1-toast';
    document.body.appendChild(t);
  }
  t.textContent = msg;
  t.className = bad ? 'bad' : '';
  t.style.display = 'block';
  t.style.opacity = '1';
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => {
    t.style.opacity = '0';
    setTimeout(() => { t.style.display = 'none'; }, 200);
  }, bad ? 4500 : 3000);
}
window.showToast = showToast;

const jobState = {
  active: false,
  startTime: null,
  endTime: null,
  durationStr: '',
  recipeId: '',
  recipeName: '',
  operator: ''
};

function formatTime(d){
  if(!d) return '';
  const date = (d instanceof Date) ? d : new Date(d);
  if(isNaN(date.getTime())) return '';
  const pad = n => String(n).padStart(2, '0');
  return `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

function formatDateTime(d){
  if(!d) return '—';
  const date = (d instanceof Date) ? d : new Date(d);
  if(isNaN(date.getTime())) return '—';
  const pad = n => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

function updateJobUI(){
  const stopBtn = document.getElementById('btn-job-stop');
  const statusBadge = document.getElementById('recipe-job-status');
  const statusText = document.getElementById('recipe-job-status-text');
  const startTimeEl = document.getElementById('recipe-job-start-time');

  const endBarBtn = document.getElementById('btn-job-end-bar');
  if(jobState.active){
    if(stopBtn) {
      stopBtn.classList.add('running');
      stopBtn.style.display = 'inline-flex';
    }
    if(endBarBtn) {
      endBarBtn.style.display = 'inline-flex';
    }
    if(statusBadge) {
      statusBadge.className = 'recipe-loaded running';
      statusBadge.style.display = 'inline-flex';
    }
    if(statusText) statusText.textContent = 'RUNNING';
    if(startTimeEl) startTimeEl.textContent = formatTime(jobState.startTime);

    if(HMI_STATE.report && jobState.startTime){
      HMI_STATE.report.startDateTime = jobState.startTime.toISOString().slice(0, 16);
      const repStart = document.getElementById('report-disp-start');
      if(repStart) repStart.textContent = formatDateTime(jobState.startTime);
      const repInp = document.getElementById('report-start');
      if(repInp && !repInp.value) repInp.value = jobState.startTime.toISOString().slice(0, 16);
    }
  } else {
    if(stopBtn) {
      stopBtn.classList.remove('running');
      stopBtn.style.display = 'none';
    }
    if(endBarBtn) {
      endBarBtn.style.display = 'none';
    }
    if(jobState.endTime && jobState.durationStr){
      if(statusBadge) {
        statusBadge.className = 'recipe-loaded stopped';
        statusBadge.style.display = 'inline-flex';
      }
      if(statusText) statusText.textContent = 'STOPPED';
      if(startTimeEl) startTimeEl.textContent = `(${jobState.durationStr})`;
    } else {
      if(statusBadge) {
        statusBadge.className = 'recipe-loaded';
        statusBadge.style.display = 'inline-flex';
      }
      if(statusText) statusText.textContent = 'READY';
      if(startTimeEl) startTimeEl.textContent = '';
    }
  }
}

function startJob(recipe, operator, customStartTime){
  const startTime = customStartTime || new Date();
  jobState.active = true;
  jobState.startTime = startTime;
  jobState.endTime = null;
  jobState.durationStr = '';
  jobState.recipeId = recipe.id || '';
  jobState.recipeName = recipe.name || '';
  jobState.operator = operator || recipe.operator || '';

  // job state persisted on server via /api/action start_job

  fetch('/api/event', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      event: 'JOB_STARTED',
      detail: `Job started for ${recipe.name}`,
      operator: jobState.operator,
      recipe: recipe.name
    })
  }).catch(()=>{});

  updateJobUI();
  // error.md Section 16.2: Reset the counters and bag tracking in startJob
  if (!HMI_STATE.report) HMI_STATE.report = {};
  HMI_STATE.report.counters = { '0-7': 0, '8-15': 0, '16-25': 0, over: 0, missed: 0, total: 0 };
  fbarxPost('/api/fbarx/cmd', { cmd: 'NEW JOB' });   // board + link counters start at zero
  window._lastSeenBagId = null;
  window._regStabilityBuf = [];
  window._lastCountedVal = null;
  window._noMatchCount = 0;
  if (typeof updateZoneCountersDisplay === 'function') updateZoneCountersDisplay();

  showToast(`JOB STARTED: ${jobState.recipeName} (${formatTime(startTime)})`);
}

function endJob(){
  if(!jobState.active) return;
  const now = new Date();
  const startTime = jobState.startTime || now;
  const elapsedSec = Math.max(0, Math.round((now - startTime) / 1000));
  const mins = Math.floor(elapsedSec / 60);
  const secs = elapsedSec % 60;
  const durationStr = `${mins}m ${secs}s`;
  const recipeName = jobState.recipeName;
  const operator = jobState.operator;

  jobState.active = false;
  jobState.endTime = now;
  jobState.durationStr = durationStr;

  // job state cleared on server via /api/action end_job

  fetch('/api/event', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      event: 'JOB_ENDED',
      detail: `Job ended. Duration: ${durationStr}`,
      operator: operator,
      recipe: recipeName
    })
  }).catch(()=>{});

  // Flush counts and job start/end time to production in SQLite DB
  const c = (HMI_STATE.report && HMI_STATE.report.counters) || { '0-7': 0, '8-15': 0, '16-25': 0, total: 0 };
  fetch('/api/production', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      recipe: recipeName,
      operator: operator,
      start_time: startTime ? startTime.toISOString() : null,
      end_time: now.toISOString(),
      force: true,
      c0_7: Number(c['0-7']) || 0,
      c8_15: Number(c['8-15']) || 0,
      c16_25: Number(c['16-25']) || 0,
      c26_w: Number(c['26-window']) || 0,
      unscored: Number(c['unscored']) || 0,
      window_mm: Number(HMI_STATE.recipe?.markWindow) || null,
      total: Number(c['total']) || 0,
      band_edges: (window.HMI_STATE && window.HMI_STATE.stn2 && window.HMI_STATE.stn2.counterBands) ? window.HMI_STATE.stn2.counterBands : null,
      mark_window: (window.HMI_STATE && window.HMI_STATE.recipe && window.HMI_STATE.recipe.markWindow) ? window.HMI_STATE.recipe.markWindow : 40
    })
  }).then(() => {
    if(typeof fetchReportFromDB === 'function') fetchReportFromDB();
  }).catch(()=>{});

  const newRec = {
    dateTime: now.toISOString(),
    imageName: recipeName,
    operator: operator,
    c0_7: Number(c['0-7']) || 0,
    c8_15: Number(c['8-15']) || 0,
    c16_25: Number(c['16-25']) || 0,
    c26_w: Number(c['26-window']) || 0,
    unscored: Number(c['unscored']) || 0,
    windowMm: Number(HMI_STATE.recipe?.markWindow) || null,
    total: Number(c['total']) || 0,
    startTime: startTime ? startTime.toISOString() : null,
    endTime: now.toISOString()
  };
  if(!HMI_STATE.report) HMI_STATE.report = { records: [] };
  if(!Array.isArray(HMI_STATE.report.records)) HMI_STATE.report.records = [];
  HMI_STATE.report.records.unshift(newRec);

  if(HMI_STATE.report){
    HMI_STATE.report.endDateTime = now.toISOString().slice(0, 16);
    const repEnd = document.getElementById('report-disp-end');
    if(repEnd) repEnd.textContent = formatDateTime(now);
    const repEndInp = document.getElementById('report-end');
    if(repEndInp) repEndInp.value = now.toISOString().slice(0, 16);
    if(typeof updateReportScreen === 'function') updateReportScreen();
  }

  updateJobUI();
  showToast(`JOB ENDED — ${recipeName} (${durationStr})`);
}
window.endJob = endJob;
window.startJob = startJob;

function restoreJobState(){ if(typeof pollState==='function') pollState(); }

function applyRecipeToHmi(r){
  const rec=normalizeRecipe(r);
  HMI_STATE.recipe=rec;                                   // calibrate now edits a draft, so replacing the object is safe
  RecipeDB.setActive(rec.id);
  // active recipe tracked on server in machine_state

  // 1. Dynamic brand name in header
  const el=document.getElementById('active-recipe-name');
  if(el) el.textContent=rec.name||'—';
  const camMatch=document.getElementById('cam-matched-name');
  if(camMatch) camMatch.textContent=(rec.name||'Veera Shivaji')+' (Front & Back)';

  // 2. Dynamic repeat & window
  const dispRepeat=document.getElementById('disp-repeat');
  if(dispRepeat) dispRepeat.textContent=rec.repeatLength;
  const dispWindow=document.getElementById('disp-window');
  if(dispWindow) dispWindow.textContent=rec.markWindow;
  if(typeof initRuler99Ticks === 'function') initRuler99Ticks();
  if(typeof computeCounterBands === 'function' && typeof updateDynamicCounterBands === 'function') {
    updateDynamicCounterBands(computeCounterBands(rec.markWindow || 40), HMI_STATE.report?.counters, window.activeCamError, true);
  }

  // 3. S-Tension target for Station 1: Register 74 must NOT change on recipe load!
  if(rec.sTensionTarget != null){
    HMI_STATE.recipe.sTensionTarget = Number(rec.sTensionTarget);
    // Keep HMI_STATE.stn1.sTension as currently set; do NOT overwrite reg 74 / stn1.sTension
  }

  // 4. Dynamic Mark offset for Station 2
  if(rec.markOffset != null){
    HMI_STATE.stn2.markOffset = Number(rec.markOffset);
  }

  // 5. Update DB Reference visual plate image
  updateDbRefPlate(rec);

  // 6. Update Calibration overlay static display elements
  updateCalOverlayFields(rec);

  // 7. Update Calibration screen if open
  if(typeof window.syncRecipeCalibrationUI === 'function') window.syncRecipeCalibrationUI();

  // 8. Update Report screen fields
  if(HMI_STATE.report){
    HMI_STATE.report.name = rec.name;
    HMI_STATE.report.imageName = rec.name;
    HMI_STATE.report.operator = rec.operator || HMI_STATE.report.operator || '';
    const rName = document.getElementById('report-name');
    if(rName) rName.value = rec.name;
    const rDispName = document.getElementById('report-disp-name');
    if(rDispName) rDispName.textContent = rec.name;
    const rOp = document.getElementById('report-operator');
    if(rOp) rOp.value = HMI_STATE.report.operator;
    const rDispOp = document.getElementById('report-disp-operator');
    if(rDispOp) rDispOp.textContent = HMI_STATE.report.operator || '—';
  }

  if(typeof refreshUI==='function') refreshUI();
}

/* =====================  SHARED ALPHA-NUMERIC KEYPAD  ===================== */
/* =====================  SHARED ALPHA-NUMERIC KEYPAD (NORMAL QWERTY)  ===================== */
const AlphaPad = (() => {
  const $=id=>document.getElementById(id);
  const rows = [
    ['1','2','3','4','5','6','7','8','9','0'],
    ['Q','W','E','R','T','Y','U','I','O','P'],
    ['A','S','D','F','G','H','J','K','L','-'],
    ['Z','X','C','V','B','N','M','.','/','BACK'],
    ['CLR','SPACE','_']
  ];
  let ctx=null, buf='', built=false, fresh=false;

  function show(){ const d=$('recipe-alpha-display'); if(!d) return; d.textContent = buf ? (buf.length>26 ? '…'+buf.slice(-25) : buf) : ' '; }
  
  function build(){
    if(built) return; built=true; const grid=$('recipe-alpha-grid'); grid.innerHTML='';
    rows.forEach(r => {
      r.forEach(k => {
        const b = document.createElement('button');
        b.type = 'button';
        if (k === 'BACK') {
          b.className = 'key-back';
          b.textContent = '⌫';
          b.title = 'Backspace';
          b.addEventListener('click', () => { fresh = false; buf = buf.slice(0, -1); show(); });
        } else if (k === 'CLR') {
          b.className = 'key-clr';
          b.textContent = 'CLR';
          b.title = 'Clear All';
          b.style.gridColumn = 'span 2';
          b.addEventListener('click', () => { fresh = false; buf = ''; show(); });
        } else if (k === 'SPACE') {
          b.textContent = 'SPACE';
          b.title = 'Space';
          b.style.gridColumn = 'span 6';
          b.addEventListener('click', () => {
            if (fresh) { buf = ''; fresh = false; }
            if (buf.length < (ctx?.max || 24)) { buf += ' '; show(); }
          });
        } else if (k === '_') {
          b.textContent = '_';
          b.style.gridColumn = 'span 2';
          b.addEventListener('click', () => {
            if (fresh) { buf = ''; fresh = false; }
            if (buf.length < (ctx?.max || 24)) { buf += '_'; show(); }
          });
        } else {
          b.textContent = k;
          b.addEventListener('click', () => {
            if (fresh) { buf = ''; fresh = false; }
            if (buf.length < (ctx?.max || 24)) { buf += k; show(); }
          });
        }
        grid.appendChild(b);
      });
    });

    $('recipe-alpha-cancel').addEventListener('click', close);
    $('recipe-alpha-ok').addEventListener('click', () => {
      const v = buf.trim(); if (ctx?.required && !v) return;
      const cb = ctx?.onOk; close(); if (cb) cb(v);
    });

    // Physical typing support for AlphaPad
    window.addEventListener('keydown', (e) => {
      const alphaModal = $('recipe-alpha-modal');
      if (!alphaModal || !alphaModal.classList.contains('open')) return;

      if (e.key === 'Escape') {
        e.preventDefault();
        close();
        return;
      }
      if (e.key === 'Enter') {
        e.preventDefault();
        $('recipe-alpha-ok')?.click();
        return;
      }
      if (e.key === 'Backspace') {
        e.preventDefault();
        fresh = false;
        buf = buf.slice(0, -1);
        show();
        return;
      }
      if (e.key === 'Delete') {
        e.preventDefault();
        fresh = false;
        buf = '';
        show();
        return;
      }
      if (e.key.length === 1 && !e.ctrlKey && !e.altKey && !e.metaKey) {
        e.preventDefault();
        if (fresh) { buf = ''; fresh = false; }
        if (buf.length < (ctx?.max || 24)) {
          buf += e.key.toUpperCase();
          show();
        }
      }
    });
  }

  function close(){ $('recipe-alpha-modal').classList.remove('open'); ctx=null; }
  function open(o){
    build(); ctx=o; buf=String(o.value||''); fresh=buf.length>0; $('recipe-alpha-title').textContent=o.title||'ENTER TEXT';
    const chips=$('recipe-alpha-chips'); chips.innerHTML='';
    (o.chips||[]).forEach(c=>{ const b=document.createElement('button'); b.type='button'; b.className='alpha-chip'; b.textContent=c;
      b.addEventListener('click',()=>{ fresh=false; buf=c; show(); }); chips.appendChild(b); });
    chips.style.display=(o.chips&&o.chips.length)?'flex':'none';
    show(); $('recipe-alpha-modal').classList.add('open');
  }
  return { open, close };
})();

